\label{defn:ndpg}
  We denote the objective function in~\eqref{eq:J-min-NonlinDPG} by
  $\mathcal{{R}}_h(\alpha, {\cdot})$, i.e.,
  \begin{equation}
    \label{eq:DPG-loss-defn}
    \mathcal{{R}}_h(\alpha, {{\mathcal{{z}}}_h}) = \| \ell - \mathcal{{A}}_\alpha({\mathcal{{z}}}_h) \|^2_{(\mathcal{{V}}_{\alpha, h})'}, \qquad
    {\mathcal{{z}}}_h \in {\mathcal{{U}}_{\alpha, h}}, \alpha \in \mathcal{{Q}},
  \end{equation}
  and refer to it as the {\bf{nonlinear residual loss function}}
  generated by $\mathcal{{V}}_{\alpha, h}$.  Its two instances, the NFOSLS and the NDPG
  loss functions, are described in \S\ref{ssec:nfosls-abstract}
  and~\S\ref{ssec:ndpg-abstract}, where their computability is also
  discussed.

\label{asm:NDPGdiff}
  We assume that
  \begin{enumerate}[label=(\alph*)]

  \item for every $\alpha \in \mathcal{{Q}}$, there is a
    ${\mathcal{{u}}} = {\mathcal{{u}}}(\alpha) \in D$ satisfying $\mathcal{{R}}(\alpha, {{\mathcal{{u}}}}) = 0$,

  \item  $\mathcal{{A}}_\alpha$ is G\^ateaux differentiable in the sense
    of~\eqref{eq:gateaux} at each ${\mathcal{{w}}} \in D$ and
    $\alpha \in \mathcal{{Q}}$; the function
    $t \mapsto d\mathcal{{A}}_\alpha({\mathcal{{w}}} + t {\mathcal{{z}}})({\mathcal{{z}}})({\mathcal{{v}}})$ is continuous
    on $[0,1]$ whenever the segment $\{{\mathcal{{w}}} + t {\mathcal{{z}}} : 0 \le t \le 1\}$
    lies in $D$; and there exists $0<C_{d}<\infty$ such that
\begin{equation}
\label{linvc}
\| d\mathcal{{A}}_\alpha({\mathcal{{w}}})({\mathcal{{z}}}) \|_{{\mathcal{{V}}'_\alpha}} \le C_{d} \| {\mathcal{{z}}}\|_{{\mathcal{{U}}_\alpha}},\quad
   \text{ for all } {\mathcal{{w}}} \in D, {\mathcal{{z}}} \in {\mathcal{{U}}_\alpha}, \mbox{and}\,\,  \alpha \in \mathcal{{Q}},
\end{equation}

  \item and there exist constants $0<\delta \le +\infty$ and $c_*>0$ such that for
    every $\alpha\in\mathcal{{Q}}$ and every
    ${\mathcal{{z}}}\in S_\delta({\mathcal{{u}}}(\alpha))\cap D$,
    \begin{equation}
      \label{eq:c-prime}
      c_*\|{\mathcal{{u}}}(\alpha)-{\mathcal{{z}}}\|_{\mathcal{{U}}_\alpha} \le \|\mathcal{{A}}_\alpha({\mathcal{{u}}}(\alpha))-\mathcal{{A}}_\alpha({\mathcal{{z}}})\|_{\mathcal{{V}}'_\alpha}.
    \end{equation}
\end{enumerate}

\label{asm:fortin-a}
  Let $\mathcal{{V}}_{\alpha, h}$ be a closed subspace of ${\mathcal{{V}}_\alpha}$.  We assume that there is a
  continuous linear operator $\varPi: {\mathcal{{V}}_\alpha} \to \mathcal{{V}}_{\alpha, h}$, referred to as a
  Fortin operator, satisfying
  \begin{equation}
    \label{eq:Fortin}
    a_\alpha({\mathcal{{w}}}_h; {\mathcal{{v}}} - \varPi {\mathcal{{v}}} ) = 0,
    \quad
    \text{ for all }
    {{\mathcal{{w}}}_h} \in D_h, {\mathcal{{v}}} \in {\mathcal{{V}}_\alpha}.
  \end{equation}

\label{hyp:sigma}
  There are constants $0 < \mu_1 \le \mu_2 < \infty$,
  $\lambda \ge 0$, and $C_\gamma \ge C_\gamma^- \ge 0$ such that, for
  every $\alpha \in \mathcal{{Q}}$, the functions
  $\sigma_\alpha \in C^1(\mathbb{{R}}^d\times\mathbb{{R}}; \mathbb{{R}}^d)$ and
  $\gamma_\alpha \in C^1(\mathbb{{R}})$ satisfy, for all
  $(p,s) \in \mathbb{{R}}^d\times\mathbb{{R}}$ and all $\xi \in \mathbb{{R}}^d$,
  \begin{subequations}
    \label{eq:sigma-asm}
    \begin{align}
      \label{eq:Q1}
      &\mu_1 |\xi|^2
      \le -\xi \cdot \partial_p\sigma_\alpha(p,s)\, \xi
        \le \mu_2 |\xi|^2,
      \\
      \label{eq:Q2}
      &| \partial_s \sigma_\alpha(p,s) |
      \le \lambda,
      \\
      \label{eq:Q3}
      &|\gamma_\alpha'(s)|
      \le C_\gamma,
        \quad
        \gamma_\alpha'(s)
        \ge -C_\gamma^-,
      \\
      \label{eq:Q4}
      &c_0  := \mu_1
      - \frac{\lambda}{\sqrt{c_P}}
      - \frac{C_\gamma^-}{c_P}
       \;>\; 0 .
    \end{align}
  \end{subequations}

\label{lem:rho-exists}
  Let Hypothesis~\ref{hyp:sigma} hold.  Then, for each fixed
  $s \in \mathbb{{R}}$, the map $p \mapsto \sigma_\alpha(p,s)$ is a
  $C^1$-isomorphism of $\mathbb{{R}}^d$ onto itself.  Its inverse
  $\rho_\alpha(\cdot, s)$ satisfying
  \begin{equation}
    \label{eq:rho-defn}
    \sigma_\alpha\bigl( \rho_\alpha(q,s), s\bigr) = q,
    \qquad (q,s) \in \mathbb{{R}}^d \times \mathbb{{R}},
  \end{equation}
  is $C^1$ jointly in $(q,s)$, with
  \begin{equation}
    \label{eq:rho-derivs}
    \partial_q \rho_\alpha(q,s)
    = \bigl[ \partial_p\sigma_\alpha(\rho_\alpha(q,s), s) \bigr]^{-1},
    \qquad
    \partial_s\rho_\alpha(q,s)
    = -\,\partial_q\rho_\alpha(q,s)\,
    \partial_s \sigma_\alpha(\rho_\alpha(q,s), s),
  \end{equation}
  and consequently
  \begin{equation}
    \label{eq:rho-bounds}
    \mu_2^{-1} |\xi|^2
    \le - \xi\cdot \partial_q\rho_\alpha(q,s)\, \xi
    \le \mu_1^{-1} |\xi|^2,
    \qquad
    |\partial_s\rho_\alpha(q,s)| \le \frac{\lambda}{\mu_1}.
  \end{equation}

\label{lem:frozen-operator}
  Let Hypothesis~\ref{hyp:sigma} hold and let $(S, \tau, c)$ be an
  admissible triple.  Then both $A_{S,\tau,c}$ and $T_{S,\tau,c}$ map
  $H(\operatorname*{div})\times\mathring{H}^1$ bijectively onto $L_2^d \times L_2$ and their
  inverses are bounded by constants depending only on $\mu_1$,
  $\mu_2$, $\lambda$, $C_\gamma$, $c_0$ and $c_P$ (and the bounds are
  uniform over admissible triples).  Moreover, for $A_{S,\tau,c}$, one
  may take
  \begin{equation}
    \label{eq:frozen-two-sided}
    c_A\, \| (q,z) \|_{H(\operatorname*{div})\times\mathring{H}^1}
    \;\le\; \bigl\| A_{S,\tau,c}(q,z) \bigr\|_{L_2}
    \;\le\; C_A\, \| (q,z) \|_{H(\operatorname*{div})\times\mathring{H}^1},
    \qquad
  \end{equation}
  for all $(q,z) \in H(\operatorname*{div})\times\mathring{H}^1$, and, for $T_{S,\tau,c}$,
  \begin{equation}
    \label{eq:frozen-transposed-two-sided}
    c_T\, \| (r,v) \|_{H(\operatorname*{div})\times\mathring{H}^1}
    \;\le\; \bigl\| T_{S,\tau,c}(r,v) \bigr\|_{L_2}
    \;\le\; C_T\, \| (r,v) \|_{H(\operatorname*{div})\times\mathring{H}^1}
  \end{equation}
  for all $(r,v) \in H(\operatorname*{div})\times\mathring{H}^1$, with
  \begin{equation}
    \label{eq:frozen-constants}
    \begin{aligned}
      C_A^2 & = 2 \max \Bigl( 1, \;
      \Bigl( \mu_2 + \tfrac{\lambda}{c_P^{1/2}} \Bigr)^2
      + \tfrac{C_\gamma^2}{c_P} \Bigr),
      \\
      c_A^{-2} & = \Bigl( 1 + c_P^{-1} \Bigr)
      \left[
        \Big( 1 + \frac{\mu_2 + \lambda\, c_P^{-1/2}}{c_0} \Big)^2
        + \Bigl( c_P^{1/2} + \frac{C_\gamma}{c_P^{1/2}\,c_0} \Bigr)^2
        + \frac{1}{c_0^2}
      \right],
      \\
      C_T^2 & = 2 + \frac{1 + \lambda^2}{\mu_1^2}
      + \frac{C_\gamma^2}{c_P},
      \\
      c_T^{-2} & = \mu_2^2 \Bigl( 1 + \frac{C_1}{c_0} \Bigr)^2
      + \left[ (1+\lambda^2)^{1/2}
        + \bigl( \lambda + C_\gamma\, c_P^{-1/2} \bigr) \frac{C_1}{c_0}
      \right]^2
      + \frac{C_1^2}{c_0^2},
    \end{aligned}
  \end{equation}
  where
  $C_1^2 := \bigl( \mu_2 + \lambda\, c_P^{-1/2} \bigr)^2 + c_P^{-1} .$

\label{prop:NDPGdiff-verif'}
  Let Hypothesis~\ref{hyp:sigma} hold.  Then, in the setting
  of~\eqref{eq:DPG-A}, the operator $\mathcal{{A}}_\alpha : {\mathcal{{U}}_\alpha} \to {\mathcal{{V}}'_\alpha}$ satisfies all
  conditions of Assumption~\ref{asm:NDPGdiff} with $D = {\mathcal{{U}}_\alpha}$ and
  $\delta = +\infty$.  Specifically:
  \begin{enumerate}[label={\rm(\alph*)}]
  \item for each $\alpha \in \mathcal{{Q}}$ there is a ${\mathcal{{u}}} = {\mathcal{{u}}}(\alpha) \in
    {\mathcal{{U}}_\alpha}$ with $\mathcal{{R}}(\alpha, {{\mathcal{{u}}}}) = 0$;
  \item the G\^ateaux derivative $d\mathcal{{A}}_\alpha({\mathcal{{w}}}) : {\mathcal{{U}}_\alpha} \to {\mathcal{{V}}'_\alpha}$
    of~\eqref{eq:gateaux} exists at each ${\mathcal{{w}}} \in {\mathcal{{U}}_\alpha}$ and
    $\alpha \in \mathcal{{Q}}$, is given by~\eqref{eq:dA}, depends continuously
    on ${\mathcal{{w}}}$ along line segments, and
    satisfies $\|d\mathcal{{A}}_\alpha({\mathcal{{w}}})({\mathcal{{z}}})\|_{{\mathcal{{V}}'_\alpha}} \le C_{d}\|{\mathcal{{z}}}\|_{{\mathcal{{U}}_\alpha}}$ with
    \begin{equation}
      \label{eq:uw-Cd}
      C_{d}^2 = 3 + c_P^{-1} + \frac{1}{\mu_1^2}
      + \Bigl( 1 + \frac{\lambda}{\mu_1} \Bigr)^2 + C_\gamma^2 ;
    \end{equation}
  \item inequality~\eqref{eq:c-prime} holds for all ${\mathcal{{z}}} \in {\mathcal{{U}}_\alpha}$,
    i.e., with $\delta = +\infty$, with $c_* = c_{d}$ given by
    \begin{equation}
      \label{eq:uw-cd}
      \frac{1}{c_{d}^2}
      = \frac{1 + c_P^{-1}}{c_T^2}
      + \Bigl( 1 + \frac{(1 + c_P^{-1})^{1/2}\, C_T}{c_T} \Bigr)^2,
    \end{equation}
    where $c_T$ and $C_T$ are the constants
    of~\eqref{eq:frozen-transposed-two-sided}; in particular $c_*$
    depends only on $\mu_1$, $\mu_2$, $\lambda$, $C_\gamma$, $c_0$ and
    $c_P$.
  \end{enumerate}
  In particular, since $\delta = +\infty$ and $D = {\mathcal{{U}}_\alpha}$, part {\rm(c)}
  implies that the ${\mathcal{{u}}}$ in part {\rm(a)} is unique, and is the
  unique minimizer in~\eqref{eq:exact-minimization}.

\label{prop:fortin-a-verif}
  Let Hypothesis~\ref{hyp:sigma} hold and adopt the discrete
  spaces~\eqref{eq:uw-discrete}.  Suppose that the nonlinearities
  preserve piecewise constants on ${\varOmega_h}$, i.e.,
  \begin{equation}
    \label{eq:P0-preserving}
    \rho_\alpha(q_h, u_h) \in P_0^d
    \quad\text{and}\quad
    \gamma_\alpha(u_h) \in P_0
    \qquad\text{for all } q_h \in P_0^d,\; u_h \in P_0 .
  \end{equation}
  Then Assumption~\ref{asm:fortin-a} holds with $D_h = {\mathcal{{U}}_{\alpha, h}}$.

\label{thm:vc-NDPG-example}
  Let Hypothesis~\ref{hyp:sigma} and~\eqref{eq:P0-preserving} hold,
  and adopt the setting of~\eqref{eq:DPG-A}
  and~\eqref{eq:uw-discrete}.  Then the NDPG loss function
  $\mathcal{{R}}_h(\alpha, {\cdot})$ of~\eqref{eq:DPG-loss-defn} is {\em globally}
  variationally correct: with $c = c_{d}^2/2$ and $C = C_{d}^2$ from
  Proposition~\ref{prop:NDPGdiff-verif'},
  the estimates~\eqref{eq:reliability}--\eqref{eq:efficiency} hold for
  every mesh and every ${\mathcal{{w}}}_h \in {\mathcal{{U}}_{\alpha, h}}$.  If, moreover, $f \in P_0$,
  then $\operatorname{{\ensuremath{\text{osc}}}}(\ell) = 0$, so that there are mesh- and
  $\alpha$-independent constants $c', C' > 0$ with
  \begin{align}
    \label{eq:ndpg-vc-example}
    c'\,\|{\mathcal{{u}}} - {\mathcal{{w}}}_h\|_{{\mathcal{{U}}_\alpha}}^2
    \le \mathcal{{R}}_h(\alpha, {{\mathcal{{w}}}_h})
    \le C'\,\|{\mathcal{{u}}} - {\mathcal{{w}}}_h\|_{{\mathcal{{U}}_\alpha}}^2,
    \qquad {\mathcal{{w}}}_h \in {\mathcal{{U}}_{\alpha, h}} .
  \end{align}

\label{cor:semilin-instance}
  Suppose that, for every $\alpha \in \mathcal{{Q}}$, the tensor
  $\kappa_\alpha \in L_\infty(\varOmega;\mathbb{{R}}^{d\times d})$ is symmetric with
  spectrum contained in $[\kappa_1,\kappa_2]$ for a.e.~$x \in \varOmega$,
  the advection vector $b_\alpha \in \mathbb{{R}}^d$ is constant with
  $|b_\alpha| \le b_*$, and $g_\alpha, \gamma_\alpha \in C^1(\mathbb{{R}})$
  satisfy $\sup |g_\alpha'| \le C_g$ and
  $\sup|\gamma_\alpha'| \le C_\gamma$, with
  $\gamma_\alpha' \ge -C_\gamma^-$.  Then~\eqref{eq:semilin-sigma}
  satisfies~\eqref{eq:Q1}--\eqref{eq:Q3} of Hypothesis~\ref{hyp:sigma} with
  \[
    \mu_1 = \kappa_1,
    \qquad
    \mu_2 = \kappa_2,
    \qquad
    \lambda = C_g\, b_*,
  \]
  and $C_\gamma, C_\gamma^-$ as given, so that whenever the smallness
  condition~\eqref{eq:Q4}
  \begin{equation}
    \label{eq:semilin-small}
    c_0 = \kappa_1
    - \frac{C_g\, b_*}{\sqrt{c_P}}
    - \frac{C_\gamma^-}{c_P}
    \; > \; 0
  \end{equation}
  holds, the NFOSLS loss is variationally correct, i.e.,
  \eqref{eq:nfosls-vc-example} holds with
  \begin{equation}
    \label{eq:Cd-c*-semilin}
    \begin{aligned}
      C_{d}^2 & = 2 \max\Bigl( 1, \;
      \Bigl( \kappa_2 + \frac{C_g\, b_*}{c_P^{1/2}} \Bigr)^2
      + \frac{C_\gamma^2}{c_P} \Bigr),
      \\
      c_*^{-2} & = \Bigl( 1 + \frac 1 {c_P}\Bigr)
      \left[
        \Bigl( 1 + \frac{\kappa_2 + C_g\, b_*\, c_P^{-1/2}}{c_0}\Bigr)^2
        + \Bigl( c_P^{1/2} + \frac{C_\gamma}{c_P^{1/2}\, c_0}\Bigr)^2
        + \frac{1}{c_0^2}
      \right],
    \end{aligned}
  \end{equation}
  with $c_0$ as in~\eqref{eq:semilin-small},
    and the NDPG loss is variationally correct when $\kappa_\alpha$ and $f$ are constant on each element of ${\varOmega_h}$.

\label{lem:kirchhoff-frozen}
  Let Hypothesis~\ref{hyp:M} hold and set
  \begin{equation}
    \label{eq:KH-cK}
    c_K := (M_1 - 2 C_M^-)\, \kappa_1 > 0,
    \qquad
    C_K := (M_2 + 2 C_M^*)\, \kappa_2 .
  \end{equation}
  Then, for every $w, \zeta \in \mathring{H}^1$ and every $\alpha \in \mathcal{{Q}}$,
  \begin{equation}
    \label{eq:KH-coercive}
    \| B_w \zeta \|_{L_2}
    \le C_K\, \| \nabla \zeta \|_{L_2},
    \qquad
    ( B_w \zeta, \nabla \zeta)_\varOmega
    \ge c_K\, \| \nabla \zeta \|^2_{L_2} .
  \end{equation}
  Both constants are independent of $w$ and of $\alpha$.  Consequently
  the same two bounds hold for the averaged map
  $\int_0^1 B_{w^t}\, dt$ generated by an arbitrary family
  $\{ w^t : t \in [0,1] \} \subset \mathring{H}^1$.

\label{thm:vc-NFOSLS-Kirchhoff}
  Let Hypothesis~\ref{hyp:M} hold.  Then the loss
  function~\eqref{eq:KH-fos-loss} is globally variationally correct on
  the entire trial space: with $c_*$ and $C_{d}$ as in
  Proposition~\ref{prop:kirchhoff-nfosls},
  \begin{equation}
    \label{eq:KH-nfosls-vc}
    \frac{c_*^2}{2}\, \| {\mathcal{{u}}} - {\mathcal{{z}}} \|^2_{{\mathcal{{U}}_\alpha}}
    \;\le\; \mathcal{{R}}_h(\alpha, {{\mathcal{{z}}}})
    \;\le\; C_{d}^2\, \| {\mathcal{{u}}} - {\mathcal{{z}}} \|^2_{{\mathcal{{U}}_\alpha}},
    \qquad {\mathcal{{z}}} \in {\mathcal{{U}}_\alpha} = H(\operatorname*{div}) \times \mathring{H}^1 .
  \end{equation}

\label{prop:kirchhoff-ndpg}
  Let Hypothesis~\ref{hyp:M} hold.  Then, in the setting
  of~\eqref{eq:KH-DPG}, all conditions of
  Assumption~\ref{asm:NDPGdiff} hold with $D = {\mathcal{{U}}_\alpha}$ and
  $\delta = +\infty$.  Specifically:
  \begin{enumerate}[label={\rm(\alph*)}]
  \item for each $\alpha \in \mathcal{{Q}}$, the element
    ${\mathcal{{u}}}(\alpha) := (u(\alpha), \hat q_n) \in {\mathcal{{U}}_\alpha}$, with $u(\alpha)$
    as in Lemma~\ref{lem:kirchhoff-wellposed} and
    $\hat q_n := \mathop{\mathrm{tr}_n}(\kappa_\alpha\nabla w_\alpha)$, satisfies $\mathcal{{R}}(\alpha, {{\mathcal{{u}}}(\alpha)}) = 0$;
    it is in fact the unique element of ${\mathcal{{U}}_\alpha}$ with this property;
  \item $\mathcal{{A}}_\alpha$ is Fr{\'{e}}chet\ differentiable at every ${\mathcal{{w}}} \in {\mathcal{{U}}_\alpha}$
    and~\eqref{linvc} holds with
    $C_{d} = \bigl[ C_K^2 + 1 \bigr]^{1/2}$;
  \item inequality~\eqref{eq:c-prime} holds for all ${\mathcal{{z}}} \in {\mathcal{{U}}_\alpha}$,
    i.e., with $\delta = +\infty$, with $c_* = c_{d}$ given by
    \begin{equation}
      \label{eq:KH-cd}
      \frac{1}{c_{d}^2}
      = \frac{1 + c_P^{-1}}{c_K^2}
      + \Bigl( 1 + \frac{(1 + c_P^{-1})^{1/2}\, C_K}{c_K} \Bigr)^2 ;
    \end{equation}
    in particular $c_*$ is independent of $\alpha \in \mathcal{{Q}}$ and of the
    mesh.
  \end{enumerate}
